<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'events']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">PROGRAMME BUILDER</span><h1 data-testid="events-page-title">Events</h1><p>Only event management data is loaded here. Use filters and select up to 100 records for permanent cleanup.</p></div><a class="button button-yellow" href="<?= base_url('admin/events/new') ?>" data-testid="events-new-button">New event <span>↗</span></a></div>
  <form class="admin-panel event-list-filters" method="get" action="<?= base_url('admin/events') ?>" data-testid="event-filter-form"><label>Search<input name="q" value="<?= esc($filters['q']) ?>" placeholder="Event name or slug" data-testid="event-search"></label><label>Status<select name="status" data-testid="event-status-filter"><option value="">All statuses</option><?php foreach(['draft','scheduled','registration_open','registration_closed','full','live','completed','cancelled','archived'] as $status): ?><option value="<?= $status ?>" <?= $filters['status']===$status?'selected':'' ?>><?= ucwords(str_replace('_',' ',$status)) ?></option><?php endforeach ?></select></label><label>Category<select name="category_id" data-testid="event-category-filter"><option value="0">All categories</option><?php foreach($categories as $category): ?><option value="<?= $category['id'] ?>" <?= (int)$filters['category_id']===(int)$category['id']?'selected':'' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select></label><button class="button button-ghost" type="submit" data-testid="event-filter-submit">Apply</button></form>
  <div class="permanent-delete-warning" data-testid="permanent-delete-warning"><strong>PERMANENT DELETE</strong><span>Deletes the event plus registrations, payments, QR tokens, attendance, email jobs/logs, schedules, media links and stored passes. This cannot be undone.</span></div>
  <div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">FILTERED LINEUP</span><h2 data-testid="admin-event-count"><?= count($events) ?> events on this page</h2></div><div class="event-bulk-actions"><label><input type="checkbox" data-event-select-all data-testid="event-select-all"> Select page</label><button class="table-action danger-action" type="button" data-bulk-event-delete data-testid="event-bulk-delete">Delete selected permanently</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Select</th><th>Event</th><th>Category</th><th>Fees</th><th>Status</th><th>Capacity</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $event): ?><tr data-testid="admin-event-row-<?= esc($event['id']) ?>"><td><input type="checkbox" name="event_ids[]" value="<?= $event['id'] ?>" form="bulk-delete-form" data-event-checkbox data-testid="event-select-<?= $event['id'] ?>"></td><td><strong><?= esc($event['name']) ?></strong><span class="table-sub">/<?= esc($event['slug']) ?></span></td><td><?= esc($event['category_name']) ?></td><td><strong>SAGEian <?= event_affiliation_fee($event,'sageian')>0?esc(money(event_affiliation_fee($event,'sageian'))):'FREE' ?></strong><span class="table-sub">Non-SAGEian <?= event_affiliation_fee($event,'non_sageian')>0?esc(money(event_affiliation_fee($event,'non_sageian'))):'FREE' ?></span></td><td><span class="<?= status_class($event['status']) ?>"><?= esc(strtoupper(str_replace('_',' ',$event['status']))) ?></span></td><td><?= esc($event['capacity']?:'∞') ?></td><td><div class="row-actions"><a class="table-action" href="<?= base_url('admin/events/'.$event['id'].'/edit') ?>" data-testid="event-edit-<?= esc($event['id']) ?>">Edit</a><a class="table-action" href="<?= base_url('events/'.$event['slug']) ?>" target="_blank" rel="noopener">View</a><form method="post" action="<?= base_url('admin/events/'.$event['id'].'/delete') ?>" data-permanent-event-form><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input type="hidden" name="confirm_name" value=""><button class="table-action danger-action" type="button" data-permanent-event-delete data-event-name="<?= esc($event['name'],'attr') ?>" data-testid="event-delete-<?= esc($event['id']) ?>">Permanent delete</button></form></div></td></tr><?php endforeach ?></tbody></table><?php if(!$events): ?><p class="empty-copy" data-testid="events-empty">No events match these filters.</p><?php endif ?></div><div class="admin-pagination"><?= $pager->links('events') ?></div></div>
  <form id="bulk-delete-form" method="post" action="<?= base_url('admin/events/bulk-delete') ?>"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input type="hidden" name="confirm_phrase" value=""></form>
</section></main>